theorem guardQ_congr (pol : Bool) {α : Type} {C C' P P' : α → Prop}
    (hC : ∀ a, C a ↔ C' a) (hP : ∀ a, C a → (P a ↔ P' a)) :
    guardQ pol C P ↔ guardQ pol C' P'

theorem BlockPlay.cons {i : ℕ} {c d : Config A} {ℓ : ℕ} {f : ℕ → Config A}
    (h : M.BlockPlay i d ℓ f) (hstep : M.Step c d) (hblk : M.Blk i c.state)
    (hacc : ¬M.Acc c.state) : M.BlockPlay i c (ℓ + 1) (consPlay c f)

theorem blk_step (hbwf : M.BlocksWellFormed k) {i : ℕ} {c d : Config A}
    (hstep : M.Step c d) (hi : M.Blk i c.state) :
    M.Blk i d.state ∨ M.Blk (i + 1) d.state

theorem binNum_fin_of_testBit {N : ℕ} {Le : Fin N → Fin N → Prop}
    (hle : ∀ a b, Le a b ↔ a ≤ b) (w : ℕ) (hw : w < 2 ^ N) (b : Fin N → Prop)
    (hb : ∀ p : Fin N, b p ↔ w.testBit (p : ℕ)) : binNum Le (fun _ => True) b = w

theorem binNum_equiv (u : B ≃ A) {LeB : B → B → Prop} {PosnB bB : B → Prop}
    {LeA : A → A → Prop} {PosnA bA : A → Prop}
    (hle : ∀ b b', LeB b b' ↔ LeA (u b) (u b')) (hp : ∀ b, PosnB b ↔ PosnA (u b))
    (hb : ∀ b, bB b ↔ bA (u b)) :
    binNum LeB PosnB bB = binNum LeA PosnA bA

theorem bitRank_equiv (u : B ≃ A) {LeB : B → B → Prop} {PosnB : B → Prop}
    {LeA : A → A → Prop} {PosnA : A → Prop}
    (hle : ∀ b b', LeB b b' ↔ LeA (u b) (u b')) (hp : ∀ b, PosnB b ↔ PosnA (u b)) (p : B) :
    bitRank LeB PosnB p = bitRank LeA PosnA (u p)

theorem bitRank_erase_min {Le : A → A → Prop} {Posn : A → Prop} {p₀ : A}
    (h₀ : Posn p₀) (hmin : ∀ q, Posn q → Le p₀ q) {p : A} (hp : Posn p) (hne : p ≠ p₀) :
    bitRank Le Posn p = bitRank Le (fun q => Posn q ∧ q ≠ p₀) p + 1

theorem isLinOrd_of_key {M K : Type} {LeK : K → K → Prop} {R : M → M → Prop}
    (hK : IsLinOrd LeK) (key : M → K) (hinj : Function.Injective key)
    (h : ∀ a b, R a b ↔ LeK (key a) (key b)) : IsLinOrd R

theorem digitNum_finsum {ι : Type} [Finite ι] {Le : A → A → Prop} {Blk : A → Prop} {B : ℕ}
    (S : Set ι) (c : ι → A → ℕ) :
    (∑ᶠ i ∈ S, digitNum Le Blk B (c i)) = digitNum Le Blk B fun e => ∑ᶠ i ∈ S, c i e

theorem ncard_setOf_equiv₂ {A B : Type} (u : B ≃ A) {RB : B → B → Prop}
    {RA : A → A → Prop} (hR : ∀ b b', RB b b' ↔ RA (u b) (u b')) :
    {p : B × B | RB p.1 p.2}.ncard = {p : A × A | RA p.1 p.2}.ncard

theorem bperm_boole (P : α → β → Prop) [DecidableRel P] :
    bperm (fun a b => if P a b then (1 : R) else 0) =
      Fintype.card {e : α ≃ β // ∀ a, P a (e a)}

theorem indepSet_equiv_iff {T T' : Type} {Adj : T → T → Prop} {Adj' : T' → T' → Prop}
    (E : T ≃ T') (hadj : ∀ x y, Adj x y ↔ Adj' (E x) (E y)) (S : T → Prop) :
    IndepSet Adj S ↔ IndepSet Adj' fun y => S (E.symm y)

theorem stretchIndep_equiv_iff {T : Type} {Adj : V → V → Prop}
    (E : T ≃ V ⊕ EdgePair Adj × W) {Left : T → Prop} {Edge : T → T → Prop}
    (hleft : ∀ x, Left x ↔ (E x).isRight = true)
    (hedge : ∀ x y, Edge x y ↔ stretchEdge Adj (E x) (E y)) (S : T → Prop) :
    (∀ x y, S x → S y → Left x → ¬Left y → ¬Edge x y) ↔
      StretchIndep Adj fun z => S (E.symm z)

theorem succPos_nextPos_of_not_max [Finite A] (hlin : IsLinOrd M.Le) {t : A}
    (ht : M.Posn t) (hmax : ¬MaxPos M.Le M.Posn t) :
    SuccPos M.Le M.Posn t (M.nextPos t)

theorem exists_roundCond (hbwf : M.BlocksWellFormed k) (hlin : IsLinOrd M.Le) {i : ℕ}
    (hi : 0 < i) {prev : A → Config A} (hprev : M.LegalBelow i prev) :
    ∃ w, M.RoundCond i prev w

theorem roundCond_greedyFrom (hbwf : M.BlocksWellFormed k) (hlin : IsLinOrd M.Le) {i : ℕ}
    {prev : A → Config A} (hprev : M.LegalBelow i prev) {t : A}
    (ht : M.Posn t) (hti : M.Blk i (prev t).state)
    (hpast : ∀ s, M.Posn s → M.Le s t → s ≠ t → M.BlkLt i (prev s).state) :
    M.RoundCond i prev (M.greedyFrom prev t)

theorem bareQ_congr (pol : Bool) {α : Type} {C C' P P' : α → Prop}
    (hC : ∀ a, C a ↔ C' a) (hP : ∀ a, C a → (P a ↔ P' a)) :
    bareQ pol C P ↔ bareQ pol C' P'

theorem posSeq_succPos {t p₁ : A} (ht : M.Posn t) (hmax : MaxPos M.Le M.Posn p₁) {j : ℕ}
    (hj : j < bitRank M.Le M.Posn p₁ - bitRank M.Le M.Posn t) :
    SuccPos M.Le M.Posn (M.posSeq t j) (M.posSeq t (j + 1))

theorem le_blk_of_blockPlay (hbwf : M.BlocksWellFormed k) {i : ℕ} {c : Config A} {ℓ : ℕ}
    {f : ℕ → Config A} (hplay : M.BlockPlay i c ℓ f) (hc : M.Blk i c.state) :
    ∀ j, j ≤ ℓ → ∀ jj, M.Blk jj (f j).state → i ≤ jj

theorem roundCond_splice (hbwf : M.BlocksWellFormed k) (hlin : IsLinOrd M.Le) {i : ℕ}
    {prev : A → Config A} (hprev : M.LegalBelow i prev) {t p₁ : A}
    (ht : M.Posn t) (hmax : MaxPos M.Le M.Posn p₁) (hti : M.Blk i (prev t).state)
    (hpast : ∀ s, M.Posn s → M.Le s t → s ≠ t → M.BlkLt i (prev s).state)
    {ℓ : ℕ} {f : ℕ → Config A}
    (hℓ : ℓ ≤ bitRank M.Le M.Posn p₁ - bitRank M.Le M.Posn t)
    (hplay : M.BlockPlay i (prev t) ℓ f)
    (hend : ℓ < bitRank M.Le M.Posn p₁ - bitRank M.Le M.Posn t →
      M.BlkLt (i + 1) (f ℓ).state → M.Acc (f ℓ).state ∨ M.Stuck (f ℓ)) :
    M.RoundCond i prev (M.splice prev t ℓ f)

theorem reach_total (hlin : IsLinOrd M.Le) (hdet : M.Deterministic) {c x y : Config A}
    (hx : Relation.ReflTransGen M.Step c x) (hy : Relation.ReflTransGen M.Step c y) :
    Relation.ReflTransGen M.Step x y ∨ Relation.ReflTransGen M.Step y x

theorem TMEmbed.derives_iff_evalDom {B : Type} {f : SimU c → B} {N : TMData B}
    (h : TMEmbed f (simTM c) N) {k : PCont c} {fr : List (SimSym c)}
    (hfr : FrameSeg k fr) (v : List ℕ) (j t : ℕ) :
    History.Derives (MRule N)
      (startWord (((SimSym.endL :: (fr ++ SimSym.mid :: valR v j t)).map sts).map f))
      [TapeLetter.halt] ↔ (k.toCont.eval v).Dom

theorem derives_map (h : TMEmbed f M N) {u v : List (TapeLetter A)}
    (hd : History.Derives (MRule M) u v) :
