theorem step_map (h : TMEmbed f M N) {u v : List (TapeLetter A)}
    (hs : History.Step (MRule M) u v) :
    History.Step (MRule N) (u.map (TapeLetter.map f)) (v.map (TapeLetter.map f))

theorem step_inversion_wordOf {x : LCfg c} {w : List (TapeLetter (SimU c))}
    (h : History.Step (MRule (simTM c)) (wordOf x) w) :
    (∃ y, lstep x = some y ∧ w = wordOf y) ∨ x.q = SimQ.acc

theorem wordOf_state_split {q : SimQ c} {L : List (SimSym c)} {s : SimSym c}
    {R : List (SimSym c)} {u v : List (TapeLetter (SimU c))} {w : SimU c}
    {m : List (TapeLetter (SimU c))}
    (h : wordOf ⟨q, L, s, R⟩ = u ++ (TapeLetter.state w :: m) ++ v) :
    u = TapeLetter.lft :: symsOf L.reverse ∧ w = stq q ∧
      m ++ v = TapeLetter.sym (sts s) :: (symsOf R ++ [TapeLetter.rgt])

theorem norm_cons {p : CPos c} {f fs : Code} (h : codeAt p = .cons f fs) {Q : SimQ c}
    (hQ : simStep Q .mid = some (dispatch p)) (g : ℕ) {fr : List (SimSym c)}
    (hfr : ∀ σ ∈ fr, FrameSym σ) (v : List ℕ) (j t : ℕ) :
    Reach (atMid Q g fr v j t)
      (atMid (.nSeekL (c₁ p)) (g - ((encVal (c := c) v).length + 1))
        (SimSym.hCons₁ (c₂ p) :: (encVal v ++ fr)) v j t)

theorem unprime_map_prime {l : List (SimSym c)}
    (hl : ∀ σ ∈ l, σ = SimSym.one ∨ σ = SimSym.com) :
    (l.map prime).map unprime = l

theorem norm_succ {p : CPos c} (h : codeAt p = .succ) {Q : SimQ c}
    (hQ : simStep Q .mid = some (dispatch p)) (g : ℕ) {fr : List (SimSym c)}
    (hfr : ∀ σ ∈ fr, FrameSym σ) (v : List ℕ) (j t : ℕ) :
    ∃ j' t', Reach (atMid Q g fr v j t) (restCfg g fr [v.headI.succ] j' t')

theorem norm_tail {p : CPos c} (h : codeAt p = .tail) {Q : SimQ c}
    (hQ : simStep Q .mid = some (dispatch p)) (g : ℕ) {fr : List (SimSym c)}
    (hfr : ∀ σ ∈ fr, FrameSym σ) (v : List ℕ) (j t : ℕ) :
    ∃ t', Reach (atMid Q g fr v j t) (restCfg g fr v.tail j t')

theorem norm_zero' {p : CPos c} (h : codeAt p = .zero') {Q : SimQ c}
    (hQ : simStep Q .mid = some (dispatch p)) (g : ℕ) {fr : List (SimSym c)}
    (hfr : ∀ σ ∈ fr, FrameSym σ) (v : List ℕ) (j t : ℕ) :
    Reach (atMid Q g fr v j t) (restCfg g fr (0 :: v) j (t - 1))

theorem IsWalk.exists_stepsIn [Finite A] (hlin : IsLinOrd M.Le) {conf : A → Config A}
    (h : M.IsWalk conf) {p₀ : A} (hp₀ : MinPos M.Le M.Posn p₀) :
    ∀ p, M.Posn p → ∃ n ≤ bitRank M.Le M.Posn p, M.StepsIn n (conf p₀) (conf p)

theorem asymm_lexOf {R : D → D → Prop} {S : α → α → Prop}
    (hR : ∀ a b, R a b → R b a → False) (hS : ∀ a b, S a b → S b a → False) (x y : D × α)
    (hxy : LexOf R S x y) (hyx : LexOf R S y x) : False

theorem eq_of_forall₂ {M : α → β → Prop} {δ : Type} {RU : α → δ → Prop} {RV : β → δ → Prop}
    (hcomp : ∀ x y ℓ ℓ', M x y → RU x ℓ → RV y ℓ' → ℓ = ℓ') {L₁ : List α} {L₂ : List β}
    (hM : List.Forall₂ M L₁ L₂) :
    ∀ {U V : List δ}, List.Forall₂ RU L₁ U → List.Forall₂ RV L₂ V → U = V

theorem forall₂_parseIx {T : D → α → β → Prop} {ws : D → List β}
    (h : ∀ s ∈ slots, List.Forall₂ (T s) (ps s) (ws s)) :
    List.Forall₂ (fun x ℓ => T x.1 x.2 ℓ) (parseIx slots ps) (slots.flatMap ws)

theorem idxMatch_mono {Lt₁ : α → α → Prop} {Lt₂ : β → β → Prop}
    (has₁ : ∀ a b, Lt₁ a b → Lt₁ b a → False) (has₂ : ∀ a b, Lt₂ a b → Lt₂ b a → False)
    (hp₁ : L₁.Pairwise Lt₁) (hp₂ : L₂.Pairwise Lt₂) {x y x' y' : _}
    (h : IdxMatch L₁ L₂ x y) (h' : IdxMatch L₁ L₂ x' y') : Lt₁ x x' ↔ Lt₂ y y'

theorem lt_getElem_iff (has : ∀ a b, Lt a b → Lt b a → False) {l : List α}
    (hl : l.Pairwise Lt) {i j : ℕ} (hi : i < l.length) (hj : j < l.length) :
